select * from customer

-- Q1. What is the total revenue generated by male vs female customer ?

select gender, SUM(purchase_amount) as revenue 
from customer
group by gender

-- Q2. which customer used a discount but still spent more than he average purchase amount?

select customer_id,purchase_amount
from customer
where purchase_amount >=(select avg(purchase_amount) from customer) and discount_applied = 'Yes'

--Q3. Which are the top 5 products with the higest average review rating ?

select item_purchased, category, avg(review_rating) as avgReview_rating
from customer 
group by item_purchased,category
order by avgreview_rating desc
limit 5

--Q4. Compare avrage purchase amount between standard and express Shipping ?

select shipping_type,avg(purchase_amount) as avgpurchase_amout
from customer
where shipping_type in ('Standard','Express')
group by shipping_type

--Q5. Do subscriber coustomer spend more ? compare average spend and total revenue betwen subscriber and non subscriber ?

select subscription_status,
count(customer_id) as total_customer,
round(avg(purchase_amount),2) as avg_spend ,
round(sum(purchase_amount),2) as total_revenue
from customer
group by subscription_status
order by avg_spend,total_revenue asc

--Q6 Which op 5 product have the highesst percentage of purchase with discount applied ?


SELECT
    item_purchased,
    ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/ COUNT(*),2) AS percentage_of_purchase
FROM customer
GROUP BY item_purchased
ORDER BY percentage_of_purchase DESC
LIMIT 5;

--Q7. Segment customer into new, returing and loyal based on their total no of privious 
-- purchase and show the count of each segment

with customer_type as(
select customer_id, previous_purchases,
case
   when previous_purchases = 1 then 'New'
   when previous_purchases between 2 and 10 then 'Returing'
   else 'Loyal'
   end 
   as customer_segment
   from customer
   )

select customer_segment,count(*) as count_of_customer
from customer_type
group by customer_segment

--Q8. What are the 3 most purchase product within each category ?

with items_counts as(
select category,
item_purchased,
count(customer_id) as total_customer,
row_number() over(partition by category order by count(customer_id) desc) as product_rank
from customer
group by category,item_purchased
)

select category,item_purchased,total_customer,product_rank
from items_counts
where product_rank<=3

--Q9 Are customer who are repeat buyer (more then 5 privious purchase) also like to subscriber ?

select subscription_status,
count(customer_id) as repeat_buyer
from customer
where purchase_amount >=5
group by subscription_status

--Q10 what is revenue contribusion of each age group ?

select age_group,
sum(purchase_amount) as revenue
from customer
group by age_group
order by revenue asc
